515	export async function startSandboxCallbackBridgeServer(input: {
516	  runner: CommandManagedRuntimeRunner;
517	  remoteCwd: string;
518	  assetRemoteDir: string;
519	  queueDir: string;
520	  bridgeToken: string;
521	  bridgeAsset?: SandboxCallbackBridgeAsset | null;
522	  host?: string;
523	  port?: number | null;
524	  pollIntervalMs?: number | null;
525	  responseTimeoutMs?: number | null;
526	  timeoutMs?: number | null;
527	  nodeCommand?: string;
528	  maxQueueDepth?: number | null;
529	  maxBodyBytes?: number | null;
530	}): Promise<StartedSandboxCallbackBridgeServer> {
531	  const timeoutMs = normalizeTimeoutMs(input.timeoutMs, DEFAULT_BRIDGE_RESPONSE_TIMEOUT_MS);
532	  const directories = sandboxCallbackBridgeDirectories(input.queueDir);
533	  const remoteEntrypoint = path.posix.join(input.assetRemoteDir, SANDBOX_CALLBACK_BRIDGE_ENTRYPOINT);
534	  if (input.bridgeAsset) {
535	    const assetClient = createCommandManagedSandboxCallbackBridgeQueueClient({
536	      runner: input.runner,
537	      remoteCwd: input.remoteCwd,
538	      timeoutMs,
539	    });
540	    await assetClient.makeDir(input.assetRemoteDir);
541	    const entrypointSource = await fs.readFile(input.bridgeAsset.entrypoint, "utf8");
542	    await assetClient.writeTextFile(remoteEntrypoint, entrypointSource);
543	  }
544	  const env = buildSandboxCallbackBridgeEnv({
545	    queueDir: input.queueDir,
546	    bridgeToken: input.bridgeToken,
547	    host: input.host,
548	    port: input.port,
549	    pollIntervalMs: input.pollIntervalMs,
550	    responseTimeoutMs: input.responseTimeoutMs,
551	    maxQueueDepth: input.maxQueueDepth,
552	    maxBodyBytes: input.maxBodyBytes,
553	  });
554	  const nodeCommand = input.nodeCommand?.trim() || "node";
555	  const startResult = await input.runner.execute({
556	    command: "sh",
557	    args: [
558	      "-lc",
559	      [
560	        `mkdir -p ${shellQuote(directories.requestsDir)} ${shellQuote(directories.responsesDir)} ${shellQuote(directories.logsDir)}`,
561	        `rm -f ${shellQuote(directories.readyFile)} ${shellQuote(directories.pidFile)}`,
562	        `nohup env ${Object.entries(env).map(([key, value]) => `${key}=${shellQuote(value)}`).join(" ")} ` +
563	          `${shellQuote(nodeCommand)} ${shellQuote(remoteEntrypoint)} ` +
564	          `>> ${shellQuote(directories.logFile)} 2>&1 < /dev/null &`,
565	        "pid=$!",
566	        `printf '%s\\n' \"$pid\" > ${shellQuote(directories.pidFile)}`,
567	        "printf '{\"pid\":%s}\\n' \"$pid\"",
568	      ].join("\n"),
569	    ],
570	    cwd: input.remoteCwd,
571	    timeoutMs,
572	  });
573	  requireSuccessfulResult("start sandbox callback bridge", startResult);
574	
575	  const readyResult = await runShell(
576	    input.runner,
577	    input.remoteCwd,
578	    [
579	      "i=0",
580	      `while [ \"$i\" -lt 200 ]; do`,
581	      `  if [ -s ${shellQuote(directories.readyFile)} ]; then`,
582	      `    cat ${shellQuote(directories.readyFile)}`,
583	      "    exit 0",
584	      "  fi",
585	      `  if [ -s ${shellQuote(directories.logFile)} ] && ! kill -0 \"$(cat ${shellQuote(directories.pidFile)} 2>/dev/null)\" 2>/dev/null; then`,
586	      `    cat ${shellQuote(directories.logFile)} >&2`,
587	      "    exit 1",
588	      "  fi",
589	      "  i=$((i + 1))",
590	      "  sleep 0.05",
591	      "done",
592	      `echo "Timed out waiting for bridge readiness." >&2`,
593	      `if [ -s ${shellQuote(directories.logFile)} ]; then cat ${shellQuote(directories.logFile)} >&2; fi`,
594	      "exit 1",
595	    ].join("\n"),
596	    timeoutMs,
597	  );
598	  requireSuccessfulResult("wait for sandbox callback bridge readiness", readyResult);
599	
600	  let readyData: { host?: string; port?: number; baseUrl?: string; pid?: number };
601	  try {
602	    readyData = JSON.parse(readyResult.stdout.trim()) as { host?: string; port?: number; baseUrl?: string; pid?: number };
603	  } catch (error) {
604	    throw new Error(
605	      `Sandbox callback bridge wrote invalid readiness JSON: ${error instanceof Error ? error.message : String(error)}`,
606	    );
607	  }
608	
609	  const host = typeof readyData.host === "string" && readyData.host.trim().length > 0
610	    ? readyData.host.trim()
611	    : "127.0.0.1";
612	  const port = typeof readyData.port === "number" && Number.isFinite(readyData.port) ? readyData.port : 0;
613	  if (!port) {
614	    throw new Error("Sandbox callback bridge did not report a listening port.");
615	  }
616	  const baseUrl =
617	    typeof readyData.baseUrl === "string" && readyData.baseUrl.trim().length > 0
618	      ? readyData.baseUrl.trim()
619	      : `http://${host}:${port}`;
620	
621	  return {
622	    baseUrl,
623	    host,
624	    port,
625	    pid: typeof readyData.pid === "number" && Number.isFinite(readyData.pid) ? readyData.pid : 0,
626	    directories,
627	    stop: async () => {
628	      const stopResult = await input.runner.execute({
629	        command: "sh",
630	        args: [
631	          "-lc",
632	          [
633	            `if [ -s ${shellQuote(directories.pidFile)} ]; then`,
634	            `  pid="$(cat ${shellQuote(directories.pidFile)})"`,
635	            "  kill \"$pid\" 2>/dev/null || true",
636	            "  i=0",
637	            "  while kill -0 \"$pid\" 2>/dev/null && [ \"$i\" -lt 40 ]; do",
638	            "    i=$((i + 1))",
639	            "    sleep 0.05",
640	            "  done",
641	            "fi",
642	            `rm -f ${shellQuote(directories.pidFile)} ${shellQuote(directories.readyFile)}`,
643	          ].join("\n"),
644	        ],
645	        cwd: input.remoteCwd,
646	        timeoutMs,
647	      });
648	      if (stopResult.timedOut) {
649	        throw new Error(buildRunnerFailureMessage("stop sandbox callback bridge", stopResult));
650	      }
651	    },
652	  };
653	}
