655	function getSandboxCallbackBridgeServerSource(): string {
656	  return `import { randomUUID, timingSafeEqual } from "node:crypto";
657	import { createServer } from "node:http";
658	import { promises as fs } from "node:fs";
659	import path from "node:path";
660	
661	const queueDir = process.env.PAPERCLIP_BRIDGE_QUEUE_DIR;
662	const bridgeToken = process.env.PAPERCLIP_BRIDGE_TOKEN;
