/** Minimal company access check using fields available on ActorContext. */
function assertCompanyAccessCtx(ctx: RequestCtx, companyId: string) {
  if (!ctx.actor) throw unauthorized();
  if (ctx.actor.type === "agent" && ctx.actor.companyId !== companyId) {
    throw forbidden("Agent key cannot access another company");
  }
  // Board actor company-list enforcement is handled by the Express auth
  // middleware before the Handler is reached.
  // TODO(cloudflare): re-enforce companyIds list in Workers auth layer.
}

function buildHandlers(
  db: Db,
