    const actorType = ctx.actor!.type === "agent" ? "agent" as const : "user" as const;
    const actorId = ctx.actor!.type === "agent"
      ? (ctx.actor!.agentId ?? "unknown-agent")
      : (ctx.actor!.userId ?? "board");
    await logActivity(db, {
