    // local_implicit / isInstanceAdmin fast-path is not available.
    // Full permission check via access service is used for all board actors.
    const allowed = await access.canUser(companyId, ctx.actor.userId, "tasks:assign");
    if (!allowed) {
      throw forbidden("Missing permission: tasks:assign");
    }
  }

