      actorType,
      actorId,
      agentId: ctx.actor!.type === "agent" ? (ctx.actor!.agentId ?? null) : null,
      runId: null,
      action: "routine.created",
      entityType: "routine",
      entityId: created.id,
      details: { title: created.title, assigneeAgentId: created.assigneeAgentId },
