23	
24	type CompanyUserRow = {
25	  id: string;
26	  principalId: string;
27	  status: string;
28	  membershipRole: string | null;
29	  createdAt: Date;
30	  userId: string | null;
31	  name: string | null;
32	  email: string | null;
33	  image: string | null;
34	};
35	
36	const PROFILE_WINDOWS = [
37	  { key: "last7", label: "Last 7 days", days: 7 },
38	  { key: "last30", label: "Last 30 days", days: 30 },
39	  { key: "all", label: "All time", days: null },
40	] as const;
41	
42	function slugifyUserPart(value: string | null | undefined) {
43	  const normalized = value
44	    ?.trim()
45	    .toLowerCase()
46	    .replace(/['"]/g, "")
47	    .replace(/[^a-z0-9]+/g, "-")
48	    .replace(/^-+|-+$/g, "");
49	  return normalized || null;
50	}
51	
52	function userSlugCandidates(row: CompanyUserRow) {
53	  const candidates = new Set<string>();
54	  const add = (value: string | null | undefined) => {
55	    const slug = slugifyUserPart(value);
56	    if (slug) candidates.add(slug);
57	  };
58	  add(row.name);
59	  add(row.email?.split("@")[0]);
60	  add(row.email);
61	  add(row.principalId);
62	  return [...candidates];
63	}
64	
65	async function resolveCompanyUser(db: Db, companyId: string, rawSlug: string): Promise<CompanyUserRow | null> {
66	  const slug = slugifyUserPart(rawSlug);
67	  if (!slug) return null;
68	
69	  const rows = await db
70	    .select({
71	      id: companyMemberships.id,
72	      principalId: companyMemberships.principalId,
73	      status: companyMemberships.status,
74	      membershipRole: companyMemberships.membershipRole,
75	      createdAt: companyMemberships.createdAt,
76	      userId: authUsers.id,
77	      name: authUsers.name,
78	      email: authUsers.email,
79	      image: authUsers.image,
80	    })
81	    .from(companyMemberships)
82	    .leftJoin(authUsers, eq(authUsers.id, companyMemberships.principalId))
83	    .where(
84	      and(
85	        eq(companyMemberships.companyId, companyId),
86	        eq(companyMemberships.principalType, "user"),
87	      ),
88	    )
89	    .orderBy(desc(companyMemberships.updatedAt))
90	    .limit(200);
91	
92	  return rows.find((row) => userSlugCandidates(row).includes(slug)) ?? null;
93	}
94	
95	function userIssueInvolvementSql(companyId: string, userId: string) {
96	  return sql<boolean>`
97	    (
98	      ${issues.createdByUserId} = ${userId}
99	      OR ${issues.assigneeUserId} = ${userId}
100	      OR EXISTS (
101	        SELECT 1
102	        FROM ${issueComments}
103	        WHERE ${issueComments.companyId} = ${companyId}
104	          AND ${issueComments.issueId} = ${issues.id}
105	          AND ${issueComments.authorUserId} = ${userId}
106	      )
107	    )
108	  `;
109	}
110	
111	function windowStart(days: number | null) {
112	  if (!days) return null;
113	  return new Date(Date.now() - days * 24 * 60 * 60 * 1000);
114	}
115	
116	function startOfUtcDay(date: Date) {
117	  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()));
118	}
119	
120	function isoDay(date: Date) {
121	  return startOfUtcDay(date).toISOString().slice(0, 10);
122	}
123	
124	function dayKeyExpr(dateSql: ReturnType<typeof sql>) {
125	  return sql<string>`to_char(date_trunc('day', ${dateSql}), 'YYYY-MM-DD')`;
126	}
127	
128	function sumNumber(column: typeof costEvents.costCents | typeof costEvents.inputTokens | typeof costEvents.cachedInputTokens | typeof costEvents.outputTokens) {
129	  return sql<number>`coalesce(sum(${column}), 0)::double precision`;
130	}
131	
132	async function loadWindowStats(
133	  db: Db,
134	  companyId: string,
135	  userId: string,
136	  key: UserProfileWindowStats["key"],
137	  label: string,
138	  from: Date | null,
139	): Promise<UserProfileWindowStats> {
140	  const involvement = userIssueInvolvementSql(companyId, userId);
141	  const openStatuses = ["backlog", "todo", "in_progress", "in_review", "blocked"];
142	  const fromIso = from?.toISOString();
143	
144	  const [issueStats] = await db
145	    .select({
146	      touchedIssues: sql<number>`count(distinct case when ${involvement} ${fromIso ? sql`and ${issues.updatedAt} >= ${fromIso}` : sql``} then ${issues.id} end)::int`,
147	      createdIssues: sql<number>`count(distinct case when ${issues.createdByUserId} = ${userId} ${fromIso ? sql`and ${issues.createdAt} >= ${fromIso}` : sql``} then ${issues.id} end)::int`,
148	      completedIssues: sql<number>`count(distinct case when ${involvement} and ${issues.status} = 'done' ${fromIso ? sql`and ${issues.completedAt} >= ${fromIso}` : sql``} then ${issues.id} end)::int`,
149	      assignedOpenIssues: sql<number>`count(distinct case when ${issues.assigneeUserId} = ${userId} and ${issues.status} in (${sql.join(openStatuses.map((status) => sql`${status}`), sql`, `)}) then ${issues.id} end)::int`,
150	    })
151	    .from(issues)
152	    .where(and(eq(issues.companyId, companyId), isNull(issues.hiddenAt)));
153	
154	  const commentConditions = [
155	    eq(issueComments.companyId, companyId),
156	    eq(issueComments.authorUserId, userId),
157	  ];
158	  if (from) commentConditions.push(gte(issueComments.createdAt, from));
159	  const [commentStats] = await db
160	    .select({ count: sql<number>`count(*)::int` })
161	    .from(issueComments)
162	    .where(and(...commentConditions));
163	
164	  const activityConditions = [
165	    eq(activityLog.companyId, companyId),
166	    eq(activityLog.actorType, "user"),
167	    eq(activityLog.actorId, userId),
168	  ];
169	  if (from) activityConditions.push(gte(activityLog.createdAt, from));
170	  const [activityStats] = await db
171	    .select({ count: sql<number>`count(*)::int` })
172	    .from(activityLog)
173	    .where(and(...activityConditions));
174	
175	  const costConditions = [
176	    eq(costEvents.companyId, companyId),
177	    userIssueInvolvementSql(companyId, userId),
178	  ];
179	  if (from) costConditions.push(gte(costEvents.occurredAt, from));
180	  const [costStats] = await db
181	    .select({
182	      costCents: sumNumber(costEvents.costCents),
183	      inputTokens: sumNumber(costEvents.inputTokens),
184	      cachedInputTokens: sumNumber(costEvents.cachedInputTokens),
185	      outputTokens: sumNumber(costEvents.outputTokens),
