688	  }, expressHandler(patchAdapter, adapterDeps));
689	
690	  router.patch("/adapters/:type/override", (req, _res, next) => {
691	    try { assertInstanceAdmin(req); next(); } catch (err) { next(err); }
692	  }, expressHandler(patchAdapterOverride, adapterDeps));
693	
694	  router.delete("/adapters/:type", (req, _res, next) => {
695	    try { assertInstanceAdmin(req); next(); } catch (err) { next(err); }
696	  }, expressHandler(deleteAdapter, adapterDeps));
697	
698	  router.post("/adapters/:type/reload", (req, _res, next) => {
699	    try { assertInstanceAdmin(req); next(); } catch (err) { next(err); }
700	  }, expressHandler(reloadAdapter, adapterDeps));
701	
702	  router.post("/adapters/:type/reinstall", (req, _res, next) => {
