router.post("/issues/:id/comments", validate(addIssueCommentSchema), async (req, res) => {
  const id = req.params.id as string;
  const issue = await svc.getById(id);
  if (!issue) {
    res.status(404).json({ error: "Issue not found" });
    return;
  }
  assertCompanyAccess(req, issue.companyId);
  if (!(await assertAgentIssueMutationAllowed(req, res, issue))) return;
  const closedExecutionWorkspace = await getClosedIssueExecutionWorkspace(issue);
  if (closedExecutionWorkspace) {
    respondClosedIssueExecutionWorkspace(res, closedExecutionWorkspace);
    return;
  }

  const actor = getActorInfo(req);
  const reopenRequested = req.body.reopen === true;
  const resumeRequested = req.body.resume === true;
  const interruptRequested = req.body.interrupt === true;
  if (resumeRequested === true && !(await assertExplicitResumeIntentAllowed(req, res, issue))) return;
  if (resumeRequested !== true && reopenRequested === true && req.actor.type === "agent") {
    if (!(await assertExplicitResumeIntentAllowed(req, res, issue))) return;
  }
  const isClosed = isClosedIssueStatus(issue.status);
  const isBlocked = issue.status === "blocked";
  const explicitMoveToTodoRequested = reopenRequested || resumeRequested === true;
  const effectiveMoveToTodoRequested =
    explicitMoveToTodoRequested ||
    shouldImplicitlyMoveCommentedIssueToTodo({
      issueStatus: issue.status,
      assigneeAgentId: issue.assigneeAgentId,
      actorType: actor.actorType,
      actorId: actor.actorId,
    });
  const hasUnresolvedFirstClassBlockers =
    isBlocked && effectiveMoveToTodoRequested
      ? (await svc.getDependencyReadiness(issue.id)).unresolvedBlockerCount > 0
      : false;
  if (resumeRequested === true && isBlocked && hasUnresolvedFirstClassBlockers) {
    res.status(409).json({ error: "Issue follow-up blocked by unresolved blockers" });
    return;
  }
  let reopened = false;
  let reopenFromStatus: string | null = null;
  let interruptedRunId: string | null = null;
  let currentIssue = issue;
  const commentReferenceSummaryBefore = await issueReferencesSvc.listIssueReferenceSummary(issue.id);

  if (effectiveMoveToTodoRequested && (isClosed || (isBlocked && !hasUnresolvedFirstClassBlockers))) {
    const reopenedIssue = await svc.update(id, { status: "todo" });
    if (!reopenedIssue) {
      res.status(404).json({ error: "Issue not found" });
      return;
    }
    reopened = true;
    reopenFromStatus = issue.status;
    currentIssue = reopenedIssue;

    await logActivity(db, {
      companyId: currentIssue.companyId,
      actorType: actor.actorType,
      actorId: actor.actorId,
      agentId: actor.agentId,
      runId: actor.runId,
      action: "issue.updated",
      entityType: "issue",
      entityId: currentIssue.id,
      details: {
        status: "todo",
        reopened: true,
        reopenedFrom: reopenFromStatus,
        source: "comment",
        ...(resumeRequested === true ? { resumeIntent: true, followUpRequested: true } : {}),
        identifier: currentIssue.identifier,
      },
    });
  }

  if (interruptRequested) {
    if (req.actor.type !== "board") {
      res.status(403).json({ error: "Only board users can interrupt active runs from issue comments" });
      return;
    }

    const runToInterrupt = await resolveActiveIssueRun(currentIssue);
    if (runToInterrupt) {
      const cancelled = await heartbeat.cancelRun(runToInterrupt.id);
      if (cancelled) {
        interruptedRunId = cancelled.id;
        await logActivity(db, {
          companyId: cancelled.companyId,
          actorType: actor.actorType,
          actorId: actor.actorId,
          agentId: actor.agentId,
          runId: actor.runId,
          action: "heartbeat.cancelled",
          entityType: "heartbeat_run",
          entityId: cancelled.id,
          details: { agentId: cancelled.agentId, source: "issue_comment_interrupt", issueId: currentIssue.id },
        });
      }
    }
  }

  const comment = await svc.addComment(id, req.body.body, {
    agentId: actor.agentId ?? undefined,
    userId: actor.actorType === "user" ? actor.actorId : undefined,
    runId: actor.runId,
  });
  await issueReferencesSvc.syncComment(comment.id);
  const commentReferenceSummaryAfter = await issueReferencesSvc.listIssueReferenceSummary(currentIssue.id);
  const commentReferenceDiff = issueReferencesSvc.diffIssueReferenceSummary(
    commentReferenceSummaryBefore,
    commentReferenceSummaryAfter,
  );

  if (actor.runId) {
    await heartbeat.reportRunActivity(actor.runId).catch((err) =>
      logger.warn({ err, runId: actor.runId }, "failed to clear detached run warning after issue comment"));
  }

  await logActivity(db, {
    companyId: currentIssue.companyId,
    actorType: actor.actorType,
    actorId: actor.actorId,
    agentId: actor.agentId,
    runId: actor.runId,
    action: "issue.comment_added",
    entityType: "issue",
    entityId: currentIssue.id,
    details: {
      commentId: comment.id,
      bodySnippet: comment.body.slice(0, 120),
      identifier: currentIssue.identifier,
      issueTitle: currentIssue.title,
      ...(resumeRequested === true ? { resumeIntent: true, followUpRequested: true } : {}),
      ...(reopened ? { reopened: true, reopenedFrom: reopenFromStatus, source: "comment" } : {}),
      ...(interruptedRunId ? { interruptedRunId } : {}),
      ...summarizeIssueReferenceActivityDetails({
        addedReferencedIssues: commentReferenceDiff.addedReferencedIssues.map(summarizeIssueRelationForActivity),
        removedReferencedIssues: commentReferenceDiff.removedReferencedIssues.map(summarizeIssueRelationForActivity),
        currentReferencedIssues: commentReferenceDiff.currentReferencedIssues.map(summarizeIssueRelationForActivity),
      }),
    },
  });

  const expiredInteractions = await issueThreadInteractionService(db).expireRequestConfirmationsSupersededByComment(
    currentIssue,
    comment,
    {
      agentId: actor.agentId,
      userId: actor.actorType === "user" ? actor.actorId : null,
    },
  );
  await logExpiredRequestConfirmations({
    issue: currentIssue,
    interactions: expiredInteractions,
    actor,
    source: "issue.comment",
  });

  // Merge all wakeups from this comment into one enqueue per agent to avoid duplicate runs.
  void (async () => {
    const wakeups = new Map<string, Parameters<typeof heartbeat.wakeup>[1]>();
    const assigneeId = currentIssue.assigneeAgentId;
    const actorIsAgent = actor.actorType === "agent";
    const selfComment = actorIsAgent && actor.actorId === assigneeId;
    const skipWake = selfComment || isClosed;
    if (assigneeId && (reopened || !skipWake)) {
      if (reopened) {
        wakeups.set(assigneeId, {
          source: "automation",
          triggerDetail: "system",
          reason: "issue_reopened_via_comment",
          payload: {
            issueId: currentIssue.id,
            commentId: comment.id,
            reopenedFrom: reopenFromStatus,
            mutation: "comment",
            ...(resumeRequested === true ? { resumeIntent: true, followUpRequested: true } : {}),
            ...(interruptedRunId ? { interruptedRunId } : {}),
          },
          requestedByActorType: actor.actorType,
          requestedByActorId: actor.actorId,
          contextSnapshot: {
            issueId: currentIssue.id,
            taskId: currentIssue.id,
            commentId: comment.id,
            wakeCommentId: comment.id,
            source: "issue.comment.reopen",
            wakeReason: "issue_reopened_via_comment",
            reopenedFrom: reopenFromStatus,
            ...(resumeRequested === true ? { resumeIntent: true, followUpRequested: true } : {}),
            ...(interruptedRunId ? { interruptedRunId } : {}),
          },
        });
      } else {
        wakeups.set(assigneeId, {
          source: "automation",
          triggerDetail: "system",
          reason: "issue_commented",
          payload: {
            issueId: currentIssue.id,
            commentId: comment.id,
            mutation: "comment",
            ...(resumeRequested === true ? { resumeIntent: true, followUpRequested: true } : {}),
            ...(interruptedRunId ? { interruptedRunId } : {}),
          },
          requestedByActorType: actor.actorType,
          requestedByActorId: actor.actorId,
          contextSnapshot: {
            issueId: currentIssue.id,
            taskId: currentIssue.id,
            commentId: comment.id,
            wakeCommentId: comment.id,
            source: "issue.comment",
            wakeReason: "issue_commented",
            ...(resumeRequested === true ? { resumeIntent: true, followUpRequested: true } : {}),
            ...(interruptedRunId ? { interruptedRunId } : {}),
          },
        });
      }
    }

    let mentionedIds: string[] = [];
    try {
      mentionedIds = await svc.findMentionedAgents(issue.companyId, req.body.body);
    } catch (err) {
      logger.warn({ err, issueId: id }, "failed to resolve @-mentions");
    }

    for (const mentionedId of mentionedIds) {
      if (wakeups.has(mentionedId)) continue;
      if (actorIsAgent && actor.actorId === mentionedId) continue;
      wakeups.set(mentionedId, {
        source: "automation",
        triggerDetail: "system",
        reason: "issue_comment_mentioned",
        payload: { issueId: id, commentId: comment.id },
        requestedByActorType: actor.actorType,
        requestedByActorId: actor.actorId,
        contextSnapshot: {
          issueId: id,
          taskId: id,
          commentId: comment.id,
          wakeCommentId: comment.id,
          wakeReason: "issue_comment_mentioned",
          source: "comment.mention",
        },
      });
    }

    for (const [agentId, wakeup] of wakeups.entries()) {
      heartbeat
        .wakeup(agentId, wakeup)
        .catch((err) => logger.warn({ err, issueId: currentIssue.id, agentId }, "failed to wake agent on issue comment"));
    }
  })();

  res.status(201).json(comment);
});

