const resetAgentRuntimeSession: Handler = async (ctx) => {
  assertBoard(ctx);
  const id = ctx.param("id")!;
  const agent = await svc.getById(id);
  if (!agent) {
    return Response.json({ error: "Agent not found" }, { status: 404 });
