// ---------------------------------------------------------------------------
// Env — Cloudflare bindings injected at runtime
// ---------------------------------------------------------------------------

export interface Env {
  // Databases
  HYPERDRIVE: { connectionString: string };

  // Object storage
  PAPERCLIP_STORAGE: R2Bucket;

  // KV — setup flags, hot config, session cache
  PAPERCLIP_KV: KVNamespace;

  // Durable Object namespaces
  TASK_DO: DurableObjectNamespace;
  AGENT_RUN_DO: DurableObjectNamespace;
  SCHEDULER_DO: DurableObjectNamespace;

  // Queues
  PAPERCLIP_QUEUE: Queue;

  // Workflows
  HEARTBEAT_WORKFLOW: Workflow;
  PLUGIN_DISPATCH_WORKFLOW: Workflow;

  // Vars (set in wrangler.toml [vars])
  DEPLOYMENT_PLATFORM: string;
  DEPLOYMENT_MODE: string;
  DEPLOYMENT_EXPOSURE: string;

  // Secrets (set via `wrangler secret put`)
  // MASTER_ENCRYPTION_KEY: string  — encrypts all other secrets stored in DB
  // SANDBOX_BRIDGE_URL: string
  // SANDBOX_BRIDGE_API_KEY: string

  // Sidecar — the Node server running alongside the Workers deployment.
  SIDECAR_URL: string;
  SIDECAR_API_KEY: string;
}

// ---------------------------------------------------------------------------
// Hono app
// ---------------------------------------------------------------------------

const app = new Hono<{ Bindings: Env }>();

// Health check — always reachable, no auth, no setup gate
app.get("/api/health", (c) =>
  c.json({
    status: "ok",
    platform: c.env.DEPLOYMENT_PLATFORM ?? "cloudflare",
    mode: c.env.DEPLOYMENT_MODE ?? "authenticated",
    ts: new Date().toISOString(),
  }),
);

// First-run setup gate — redirect to /setup until SETUP_COMPLETED is "true"
app.use("*", async (c, next) => {
  // Allow the setup routes and health check through unconditionally
  if (c.req.path === "/api/health" || c.req.path.startsWith("/setup")) {
    return next();
  }

  const setupCompleted = await c.env.PAPERCLIP_KV.get("SETUP_COMPLETED");
  if (setupCompleted !== "true") {
    return c.redirect("/setup");
  }

  return next();
});

// Delegate /setup/* to the setup sub-app.
app.all("/setup/*", async (c) => {
  const setupSub = createSetupApp(c.env);
  const url = new URL(c.req.url);
  url.pathname = url.pathname.replace(/^\/setup/, "") || "/";
  const rewritten = new Request(url.toString(), c.req.raw);
  return setupSub.fetch(rewritten);
});

// Exact "/setup" (no trailing slash) — forward as "/"
app.all("/setup", async (c) => {
  const setupSub = createSetupApp(c.env);
  const url = new URL(c.req.url);
  url.pathname = "/";
  const rewritten = new Request(url.toString(), c.req.raw);
  return setupSub.fetch(rewritten);
});

// ---------------------------------------------------------------------------
// Default export — Workers fetch handler
// ---------------------------------------------------------------------------

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    // Boot the Cloudflare implementations on first request (idempotent).
    bootCloudflare(env);

    // ---------------------------------------------------------------------------
    // Per-request service instantiation
    // ---------------------------------------------------------------------------
    const sidecar = new SidecarClient({
      baseUrl: env.SIDECAR_URL,
      apiKey: env.SIDECAR_API_KEY,
    });
    const skillsService = new CfCompanySkillsService(env.PAPERCLIP_STORAGE, sidecar);
    const instructionsService = new CfAgentInstructionsService(env.PAPERCLIP_STORAGE);

    void skillsService;
    void instructionsService;

    // Create the DB and storage service for this request.
    const db = createHyperdriveDb(env.HYPERDRIVE);
    const r2Provider = new R2Provider(env.PAPERCLIP_STORAGE, {
      bucket: env.STORAGE_R2_BUCKET ?? "paperclip-storage",
      prefix: env.STORAGE_R2_PREFIX ?? "",
    });
    // Cast to the server's StorageService type — structurally identical at runtime.
    const storage = createCfStorageService(r2Provider) as unknown as import(
      "../../../server/src/storage/types.js"
    ).StorageService;

    const deploymentMode = (env.DEPLOYMENT_MODE === "local_trusted"
      ? "local_trusted"
      : "authenticated") as "local_trusted" | "authenticated";

    // Auth resolver called per-route inside mountExpressRouter.
    const resolveActor = (req: Request) =>
      resolveActorFromRequest(req, db, { deploymentMode });

    const mountOptions = { db, storage, resolveActor };

    // ---------------------------------------------------------------------------
    // Mount route groups
    // The "companies" group has the /companies prefix (app.use("/companies", ...))
    // in server/src/app.ts; all others are mounted at the root.
    // We prepend /api to match how the Express server exposes routes under /api/*.
    // ---------------------------------------------------------------------------

    // Companies (prefix: /api/companies)
    mountExpressRouter(app, companyRoutes(db, storage), "/api/companies", mountOptions);

    // Routes registered without a prefix (the router itself contains full paths
    // like /companies/:id/agents which already encode /companies/...).
    mountExpressRouter(app, agentRoutes(db, {}), "/api", mountOptions);
    mountExpressRouter(app, assetRoutes(db, storage), "/api", mountOptions);
    mountExpressRouter(app, projectRoutes(db), "/api", mountOptions);
    mountExpressRouter(app, issueRoutes(db, storage, {}), "/api", mountOptions);
    mountExpressRouter(app, issueTreeControlRoutes(db), "/api", mountOptions);
    mountExpressRouter(app, routineRoutes(db, {}), "/api", mountOptions);
    mountExpressRouter(app, environmentRoutes(db, {}), "/api", mountOptions);
    mountExpressRouter(app, executionWorkspaceRoutes(db), "/api", mountOptions);
    mountExpressRouter(app, goalRoutes(db), "/api", mountOptions);
    mountExpressRouter(app, approvalRoutes(db, {}), "/api", mountOptions);
    mountExpressRouter(app, secretRoutes(db), "/api", mountOptions);
    mountExpressRouter(app, costRoutes(db, {}), "/api", mountOptions);
    mountExpressRouter(app, activityRoutes(db), "/api", mountOptions);
    mountExpressRouter(app, dashboardRoutes(db), "/api", mountOptions);
    mountExpressRouter(app, userProfileRoutes(db), "/api", mountOptions);
    mountExpressRouter(app, sidebarBadgeRoutes(db), "/api", mountOptions);
    mountExpressRouter(app, sidebarPreferenceRoutes(db), "/api", mountOptions);
    mountExpressRouter(app, inboxDismissalRoutes(db), "/api", mountOptions);
    mountExpressRouter(app, instanceSettingsRoutes(db), "/api", mountOptions);
    mountExpressRouter(app, llmRoutes(db), "/api", mountOptions);
    mountExpressRouter(app, authRoutes(db), "/api", mountOptions);

    // R2-native upload endpoints (replaces multer-based routes).
    mountUploadRoutes(app, db);

    // ---------------------------------------------------------------------------
    // Skipped routes (Node-only features) — return 501 with TODO comment.
    // ---------------------------------------------------------------------------
    // adapterRoutes        — reads packages from disk via fs
    // pluginRoutes         — SSE streams, child processes, scoped API
    // pluginUiStaticRoutes — fs.readFileSync / res.sendFile
    // companySkillRoutes   — local filesystem (CF version: cf-company-skills.ts)
    // accessRoutes         — reads bundled SKILL.md files from disk
    // instanceDatabaseBackupRoutes — pg_dump subprocess

    // Placeholder fallthrough for any unmounted or skipped routes
    app.all("/api/*", (c) =>
      c.json(
        {
          error: "This API route is not available in the Cloudflare Workers deployment.",
          code: "NOT_IMPLEMENTED",
        },
        501,
      ),
    );

    // Catch-all for non-API requests — serve the Pages SPA.
    app.all("*", (c) =>
      c.html(
        `<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>Paperclip</title></head>
<body>
  <p>Loading Paperclip UI... If this persists, the Pages build may not be deployed yet.</p>
</body></html>`,
      ),
    );

    return app.fetch(request, env, ctx);
  },

  // -------------------------------------------------------------------------
  // Queues consumer — processes plugin job dispatch and heartbeat messages
  // -------------------------------------------------------------------------
  async queue(batch: MessageBatch<unknown>, env: Env): Promise<void> {
    for (const message of batch.messages) {
      const body = message.body as Record<string, unknown>;
      const type = body?.type as string | undefined;

      if (type === "plugin_job_dispatch") {
        const pluginJobId = body.pluginJobId as string;
        const pluginSlug = body.pluginSlug as string;
        const companyId = body.companyId as string;
        const executorMode = (body.executorMode as "sandbox_bridge" | "container") ?? "sandbox_bridge";

        try {
          await env.PLUGIN_DISPATCH_WORKFLOW.create({
            id: `plugin-job-${pluginJobId}`,
            params: { pluginJobId, pluginSlug, companyId, executorMode },
          });
          message.ack();
        } catch (err) {
          console.error(
            `[Queue] Failed to start PluginDispatchWorkflow for job ${pluginJobId}: ${
              err instanceof Error ? err.message : String(err)
            }`,
          );
          message.retry();
        }
        continue;
      }

      if (type === "heartbeat_dispatch") {
        const agentId = body.agentId as string;
        const companyId = body.companyId as string;
        const runId = body.runId as string;
        const taskId = body.taskId as string | undefined;

        try {
          await env.HEARTBEAT_WORKFLOW.create({
            id: `heartbeat-${runId}`,
            params: { agentId, companyId, runId, taskId },
          });
          message.ack();
        } catch (err) {
          console.error(
            `[Queue] Failed to start HeartbeatWorkflow for run ${runId}: ${
              err instanceof Error ? err.message : String(err)
            }`,
          );
          message.retry();
        }
        continue;
      }

      // Unknown message type — ack to avoid infinite retries
      console.warn(`[Queue] Unknown message type: ${type}`);
      message.ack();
    }
  },

  // -------------------------------------------------------------------------
  // Cron Triggers — heartbeat sweep, budget checks, DB backup
  // -------------------------------------------------------------------------
  async scheduled(event: ScheduledEvent, env: Env, _ctx: ExecutionContext): Promise<void> {
    const cron = event.cron;
    console.log(`[Cron] Firing cron: ${cron}`);

    if (cron === "*/5 * * * *") {
      // Heartbeat sweep — find agents that are due and enqueue heartbeat jobs
      const db = createHyperdriveDb(env.HYPERDRIVE);
      await runHeartbeatSweep(env, db);
    } else if (cron === "0 * * * *") {
      // Budget threshold check
      // TODO: implement by calling the internal budget service endpoint
      console.log("[Cron] Budget check — not yet implemented");
    } else if (cron === "0 3 * * *") {
      // Daily DB backup to R2
      // TODO: implement by triggering a Workflow that dumps Postgres to R2
      console.log("[Cron] DB backup — not yet implemented");
    }
  },
};

// ---------------------------------------------------------------------------
// Named Durable Object + Workflow exports
// ---------------------------------------------------------------------------

export { TaskDO } from "../runtime/task-do.js";
export { AgentRunDO } from "../runtime/agent-run-do.js";
export { SchedulerDO } from "../scheduler/scheduler-do.js";
export { HeartbeatWorkflow } from "../runtime/workflows/heartbeat.js";
export { PluginDispatchWorkflow } from "../runtime/workflows/plugin-dispatch.js";

